const vocabularyMicroSkill = (termId) => {
  if (["vocab:gradient", "vocab:tangent", "vocab:increasing", "vocab:decreasing"].includes(termId)) return skill("gradient-on-curve");
  if (["vocab:function", "vocab:gradient-function"].includes(termId)) return skill("gradient-function");
  if (["vocab:f-prime-notation", "vocab:dy-dx-notation", "vocab:derivative"].includes(termId)) return skill("derivative-notation");
  if (termId === "vocab:d-dx-operator") return skill("differentiation-operator");
  return skill("power-rule");
};

